INSERT INTO `v1_00a188047dafd3dd238bec55fb1c18abe36362f169f9ab56571642bc85c9c687` VALUES (0, 10, 1, 11, "そりゃそうですよね……\nいきなり前のめり過ぎ太郎でした……", 0, 1, 72033, 1, 72, 0);
